css:
& .am-head h1 { font-family: var(--head-font); font-weight: 800; font-size: calc(34px * var(--am-scale, 1)); letter-spacing: 0.01em; text-transform: uppercase; }
& .am-panel-head h2 { font-family: var(--head-font); font-weight: 800; font-size: calc(16px * var(--am-scale, 1)); letter-spacing: 0.03em; text-transform: uppercase; }
& .am-panel-id { font-family: var(--head-font); font-weight: 800; }
@media (max-width: 760px) {
  & .am-head h1 { font-size: calc(27px * var(--am-scale, 1)); }
}
& .am-panel-head { background-color: var(--head-bg); color: var(--head-fg); background-image: radial-gradient(color-mix(in srgb, var(--head-fg) 22%, transparent) 1px, transparent 1.3px); background-size: 5px 5px; }
& .am-panel-id { background: var(--head-fg); color: var(--head-bg); }
& .am-panel-meta { color: var(--head-fg); }
& .am-panel-head .am-comment-btn { color: var(--head-fg); }
& .am-panel:hover .am-panel-head .am-comment-btn { border-color: color-mix(in srgb, var(--head-fg) 55%, transparent); }
& .am-panel-head .am-comment-btn:hover, & .am-panel-head .am-comment-btn:focus-visible, & .am-panel-head .am-comment-btn[aria-expanded="true"], & .am-panel-head .am-comment-btn.am-comment-btn--on { color: var(--head-fg); border-color: var(--head-fg); }
